def unwrap(tp):
    orig = eval(tp) if isinstance(tp, str) else tp
    if isinstance(tp, str):
        tp = eval(tp)
    if hasattr(tp, "__origin__"):
        tp = tp.__origin__
    if hasattr(tp, "__args__"):
        tp = tp.__args__[0]
    if hasattr(tp, "__metadata__"):
        tp = tp.__metadata__[0]
        return unwrap(tp)
    if any(
        str(tp).startswith(x)
        for x in ["typing.Union", "typing.Optional", "Union", "Optional"]
    ):
        tp = orig.__args__[0]

    return tp if isinstance(tp, type) else tp.__origin__


