@dataclass
class PyProject(BaseModel):
    project: Project
    build_system: Annotated[BuildSystem, Field(alias="build-system")]
    tool: Mapping[str, Any] | None = None
    dependency_groups: Annotated[
        Mapping[str, Sequence[str]], Field(alias="dependency-groups")
    ] = None
    repository: Repository | None = None

    def __post_init__(self, **_kwargs):
        if self.project.urls is not None:
            github_url = first_true(self.project.urls, lambda x: "github" in x)

            if github_url:
                org, repo = org_and_repo_from_url(github_url)
                self.repository = Repository(org=org, repo=repo, url=github_url)
        return self

    @classmethod
    def fromtoml(cls, path: Path | str | None = None) -> PyProject:
        from pathlib import Path

        if path is None or Path(str(path)).is_dir():
            from mbpy.pkg.toml import find_toml

            path = find_toml()
        if path is None:
            raise ValueError("No path provided and no pyproject.toml found.")
        import tomlkit

        path = Path(str(path)).resolve()
        data = tomlkit.loads(path.read_text()).unwrap()
        return cls(**data)


